  '.mdstudio-theme-card { display: flex; flex-direction: column; gap: 6px; min-width: 0; padding: 6px; border: 0.5px solid var(--mdstudio-ui-border-3); border-radius: var(--mdstudio-ui-radius-md); background: var(--mdstudio-ui-card-bg); color: var(--mdstudio-ui-fg-1); text-align: left; cursor: pointer; transition: border-color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease), box-shadow var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease), background-color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease); }',
