  '.mdstudio-theme-card-edit { position: absolute; bottom: 5px; right: 5px; width: 22px; height: 22px; padding: 0; border: 0; border-radius: 6px; background: transparent; color: var(--mdstudio-ui-fg-2); display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: background-color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease), color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease); }',
