  '.mdstudio-swatch-corner.is-br { border-bottom: 1.5px solid transparent; border-right: 1.5px solid transparent; align-self: flex-end; }',
  '.mdstudio-swatch-badge { width: 9px; height: 7px; border-radius: 2px; flex: none; }',
