  '.mdstudio-swatch-token { height: 2px; border-radius: 1px; }',
  '.mdstudio-swatch-card { height: 12px; border-radius: 1px 3.5px 3.5px 1px; border-left: 2px solid transparent; padding: 0 5px; display: flex; align-items: center; }',
