  '.mdstudio-capsule-track.is-stepper { grid-template-columns: 32px repeat(4, minmax(0, 1fr)) 32px; }',
  '.mdstudio-capsule-seg, .mdstudio-capsule-step { display: inline-flex; align-items: center; justify-content: center; height: 28px; padding: 0 2px; border: 0; border-radius: 14px; background: transparent; color: var(--mdstudio-ui-fg-2); font-family: var(--mdstudio-ui-font-code); font-size: 11.5px; font-weight: 500; cursor: pointer; transition: background-color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease), color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease); }',
