  '.mdstudio-custom-chips { flex: 1; min-width: 0; display: flex; align-items: center; gap: 5px; overflow-x: auto; scrollbar-width: none; padding: 1px 0; }',
  '.mdstudio-custom-chips::-webkit-scrollbar { display: none; }',
  '.mdstudio-custom-chip { flex: none; display: inline-flex; align-items: center; gap: 5px; max-width: 160px; height: 25px; padding: 0 9px; border: 0.5px solid var(--mdstudio-ui-border-3); border-radius: 999px; background: var(--mdstudio-ui-card-bg); color: var(--mdstudio-ui-fg-2); font: inherit; font-size: 11.5px; font-weight: 500; cursor: pointer; white-space: nowrap; transition: background-color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease), color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease), border-color var(--mdstudio-ui-dur-fast) var(--mdstudio-ui-ease); }',
  '.mdstudio-custom-chip:hover { color: var(--mdstudio-ui-fg-1); border-color: var(--mdstudio-ui-border-2); }',
